import {
  PROJECT_TYPES, createProject, createNeed, updateNeed, createGuardrail, applyPulseUpdate, promoteCandidate, projectAppearsInState,
  archiveProject, restoreProject, assertCanDelete, makeBackup, bumpProjectRevision, setProjectNext,
  editPulseEntry, removePulseEntry, restorePulseEntry, buildProjectBrief, makeProjectUpdatePrompt,
  validateProjectUpdatePacket, previewProjectUpdatePacket, parseProjectUpdatePacketText, createPulseEntry,
  makeProjectBootstrapPrompt, validateProjectBootstrapPacket, previewProjectBootstrapPacket, parseProjectBootstrapPacketText
} from './domain.js?v=statezect-public-v1-0-0';
import {
  ensureMeta, putProject, getProject, savePulse, savePulseAndNeeds, saveProjectAndNeeds, saveProjectAndGuardrail,
  deletePulseEntryAndSaveProject, deleteNeedAndSaveProject, putGuardrail, deleteProjectCascade, replaceAllFromBackup, mergeProjectPack,
  resetAllData, readAll, isPacketApplied, applyProjectUpdatePacket, applyProjectBootstrapPacket, saveProjectBootstrap
} from './db.js?v=statezect-public-v1-0-0';
import { initPwaRuntime, checkForPwaUpdate } from './pwa-runtime.js?v=statezect-public-v1-0-0';

const app = document.querySelector('#app');
const modalRoot = document.querySelector('#modal-root');
let view = 'pulse';
let selectedProjectId = null;
let cache = { projects: [], pulseEntries: [], needs: [], guardrails: [] };

const esc = value => String(value ?? '').replace(/[&<>'"]/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]));
const fmt = value => value ? new Intl.DateTimeFormat(undefined,{month:'short',day:'numeric',hour:'numeric',minute:'2-digit'}).format(new Date(value)) : '—';
const typeLabel = type => PROJECT_TYPES[type]?.label || 'General';
const PROJECT_TYPE_ORDER = ['general','software','writing','making','film','research'];
const allProjectNeeds = id => cache.needs.filter(n => n.projectId === id);
const projectNeeds = id => allProjectNeeds(id).filter(n => n.state !== 'done').sort((a,b)=>Number(b.isNext)-Number(a.isNext)||b.updatedAt.localeCompare(a.updatedAt));
const completedNeeds = id => allProjectNeeds(id).filter(n => n.state === 'done').sort((a,b)=>(b.resolvedAt||b.updatedAt).localeCompare(a.resolvedAt||a.updatedAt));
const projectGuardrails = id => cache.guardrails.filter(g => g.projectId === id && g.state !== 'retired');
const projectEntries = id => cache.pulseEntries.filter(e => e.projectId === id && !e.removedAt).sort((a,b)=>b.occurredAt.localeCompare(a.occurredAt));
const removedEntries = id => cache.pulseEntries.filter(e => e.projectId === id && e.removedAt).sort((a,b)=>b.removedAt.localeCompare(a.removedAt));
const nextNeed = project => projectNeeds(project.id).find(n => n.id === project.nextNeedId) || projectNeeds(project.id).find(n => n.isNext) || null;
const currentWorldProjects = () => cache.projects.filter(p => p.lifecycle !== 'archived').sort((a,b)=>b.updatedAt.localeCompare(a.updatedAt));
const stateFocusProjects = () => cache.projects.filter(projectAppearsInState).sort((a,b)=>b.updatedAt.localeCompare(a.updatedAt));
const archivedProjects = () => cache.projects.filter(p => p.lifecycle === 'archived').sort((a,b)=>b.updatedAt.localeCompare(a.updatedAt));

const THEME_KEY = 'nivareq-pulse-theme';
const THEMES = {
  day: { label:'Day', color:'#f4f6fb' },
  night: { label:'Night', color:'#090b12' },
  oled: { label:'OLED', color:'#000000' },
  dusk: { label:'Dusk', color:'#15101d' },
  ocean: { label:'Ocean', color:'#07131a' },
  forest: { label:'Forest', color:'#09140f' },
  ember: { label:'Ember', color:'#160d09' },
  plum: { label:'Plum', color:'#160b16' },
  sand: { label:'Sand', color:'#f4efe6' }
};
function currentTheme(){ const value=document.documentElement.dataset.theme||'night'; return THEMES[value]?value:'night'; }
function applyTheme(theme,{persist=true}={}){ const chosen=THEMES[theme]?theme:'night';document.documentElement.dataset.theme=chosen;document.querySelector('meta[name="theme-color"]')?.setAttribute('content',THEMES[chosen].color);if(persist){try{localStorage.setItem(THEME_KEY,chosen);}catch{}}return chosen; }

async function refresh(){ cache=await readAll(); }
function toast(message){ const el=document.createElement('div');el.textContent=message;el.className='toast';document.body.append(el);setTimeout(()=>el.remove(),2400); }
function closeModal(){ modalRoot.innerHTML=''; }
function autoGrow(el){ if(!el?.matches?.('textarea[data-autogrow]'))return;el.style.height='auto';el.style.height=`${Math.min(el.scrollHeight,260)}px`; }
function wireAutoGrow(root=document){ root.querySelectorAll?.('textarea[data-autogrow]').forEach(autoGrow); }
document.addEventListener('input',e=>autoGrow(e.target));
function openSheet(title,content,onReady){
  modalRoot.innerHTML=`<div class="modal-backdrop" data-dismiss><section class="sheet" role="dialog" aria-modal="true" aria-label="${esc(title)}"><div class="sheet-head"><h2>${esc(title)}</h2><button class="close" data-close aria-label="Close">×</button></div>${content}</section></div>`;
  modalRoot.querySelector('[data-close]').onclick=closeModal;
  modalRoot.querySelector('[data-dismiss]').onclick=e=>{if(e.target===e.currentTarget)closeModal();};
  const sheet=modalRoot.querySelector('.sheet');onReady?.(sheet);wireAutoGrow(sheet);
}
async function copyText(text,label='Copied'){ try{await navigator.clipboard.writeText(text);toast(label);}catch{openSheet('Copy text',`<textarea class="copy-box" data-autogrow readonly>${esc(text)}</textarea><p class="meta">Select and copy the text above.</p>`);} }
async function shareText(title,text){ if(navigator.share){try{await navigator.share({title,text});return;}catch(err){if(err?.name==='AbortError')return;}}await copyText(text,'Copied for sharing'); }

function cardHTML(p){
  const need=nextNeed(p);
  const cp=p.type==='software'?[p.checkpoints?.published&&`<span class="checkpoint">Public · ${esc(p.checkpoints.published)}</span>`,p.checkpoints?.accepted&&`<span class="checkpoint">Baseline · ${esc(p.checkpoints.accepted)}</span>`,p.checkpoints?.candidate&&`<span class="checkpoint">Candidate · ${esc(p.checkpoints.candidate)}</span>`].filter(Boolean).join(''):'';
  const lifecycleBadge=p.lifecycle!=='active'?`<span class="badge lifecycle ${esc(p.lifecycle)}">${esc(p.lifecycle)}</span>`:'';
  const attentionBadge=p.attention!=='clear'?`<span class="badge ${esc(p.attention)}">${esc(p.attention.replace('_',' '))}</span>`:'';
  const badges=lifecycleBadge||attentionBadge?`<div class="card-badges">${lifecycleBadge}${attentionBadge}</div>`:'';
  return `<button type="button" class="project-card" data-project="${esc(p.id)}" aria-label="Open ${esc(p.name)}"><div class="card-top"><div><div class="meta">${esc(typeLabel(p.type))} · ${esc(p.stage)}</div><h4>${esc(p.name)}</h4></div>${badges}</div><div class="summary">${esc(p.currentSummary||'No current situation recorded yet.')}</div><div class="next-line"><span>Next</span> · ${esc(need?.title||p.nextSummary||'Nothing marked next')}</div>${cp?`<div class="checkpoint-row">${cp}</div>`:''}</button>`;
}
function navButton(key,icon,label){return `<button class="nav-btn ${view===key?'active':''}" data-nav="${key}"><span>${icon}</span>${label}</button>`;}
function shell(content){
  app.innerHTML=`<div class="app-shell"><header class="topbar"><div class="brand"><div><h1>StateZect</h1><div class="maker">A NivareQ™ project</div></div><div class="build" aria-hidden="true"></div></div></header><main>${content}</main><nav class="bottom-nav" aria-label="Main navigation">${navButton('pulse','◉','State')}${navButton('projects','◇','ProZects')}${navButton('archive','▣','Archive')}${navButton('settings','•••','More')}</nav></div>`;
  app.querySelectorAll('[data-nav]').forEach(b=>b.onclick=()=>{view=b.dataset.nav;selectedProjectId=null;render();});
}
function render(){ if(selectedProjectId)return renderProject();if(view==='projects')return renderProjects();if(view==='archive')return renderArchive();if(view==='settings')return renderSettings();return renderPulse(); }
function renderPulse(){
  const projects=stateFocusProjects(),focusIds=new Set(projects.map(p=>p.id)),attention=projects.filter(p=>['blocked','needs_attention'].includes(p.attention)),openNeeds=cache.needs.filter(n=>focusIds.has(n.projectId)&&n.state!=='done');
  shell(`<section class="hero"><div class="eyebrow">Current world</div><h2>Know the state of your ProZects.</h2><p>Your ProZects, their latest truth, and what needs attention next.</p></section><div class="stats"><div class="stat"><strong>${projects.length}</strong><span>In focus</span></div><div class="stat"><strong>${attention.length}</strong><span>Need attention</span></div><div class="stat"><strong>${openNeeds.length}</strong><span>Open needs</span></div></div>${attention.length?`<div class="attention-box"><strong>${attention.length} ProZect${attention.length===1?'':'s'} need attention</strong><p>${attention.map(p=>esc(p.name)).join(' · ')}</p></div>`:''}<div class="section-head"><h3>ProZect state</h3><button class="text-btn" id="add-project">+ ProZect</button></div><div class="project-list">${projects.length?projects.map(cardHTML).join(''):`<div class="empty">Nothing needs active focus right now.<br><br><span class="meta">Paused, completed, released, and maintenance ProZects remain available under ProZects.</span><br><br><button class="primary-btn" id="empty-add">Create a ProZect</button></div>`}</div>`);
  app.querySelector('#add-project')?.addEventListener('click',openAddProject);app.querySelector('#empty-add')?.addEventListener('click',openAddProject);
}
function renderProjects(){const projects=currentWorldProjects();shell(`<section class="hero"><div class="eyebrow">ProZects</div><h2>Everything in motion.</h2><p>ProZect types change the shortcuts, not the underlying truth model.</p></section><div class="section-head"><h3>${projects.length} ProZects</h3><button class="primary-btn" id="add-project">+ ProZect</button></div><div class="project-list">${projects.map(cardHTML).join('')||'<div class="empty">Nothing here yet.</div>'}</div>`);app.querySelector('#add-project').onclick=openAddProject;}
function renderArchive(){const rows=archivedProjects();shell(`<section class="hero"><div class="eyebrow">Archive</div><h2>Out of the active world.</h2><p>Archived ProZects can be restored. Permanent deletion is only possible from here.</p></section><div class="project-list">${rows.map(cardHTML).join('')||'<div class="empty">Archive is empty.</div>'}</div>`);}
function renderSettings(){
  const theme=currentTheme();
  shell(`<section class="hero"><div class="eyebrow">More</div><h2>Data stays yours.</h2><p>StateZect is local-first: no account, analytics, cloud service, or embedded AI transmission.</p></section><div class="settings-list">
    <div class="settings-item"><h3>How StateZect Works</h3><p>A compact guide to ProZects, History, Needs, Next, Guardrails, Archive, ProZect Briefs, and data exchange.</p><button class="ghost-btn" id="how-pulse">Open guide</button></div>
    <div class="settings-item"><h3>Detailed Manual</h3><p>A start-from-zero, step-by-step manual for someone who has never used StateZect before.</p><button class="ghost-btn" id="detailed-manual">Open detailed manual</button></div>
    <div class="settings-item"><h3>Appearance</h3><p>Nine curated themes share one registry: Day, Night, OLED, Dusk, Ocean, Forest, Ember, Plum, and Sand.</p><div class="theme-picker" role="group" aria-label="Appearance">${Object.entries(THEMES).map(([key,value])=>`<button type="button" class="theme-choice ${theme===key?'selected':''}" data-theme-choice="${key}"><span class="theme-dot ${key}"></span>${value.label}</button>`).join('')}</div></div>
    <div class="settings-item"><h3>Export backup</h3><p>Download a complete versioned backup of ProZects, History, Needs, and Guardrails.</p><button class="ghost-btn" id="export">Export backup</button></div>
    <div class="settings-item"><h3>Restore full backup</h3><p>A full restore replaces the current StateZect database after validation.</p><button class="ghost-btn" id="import">Choose backup</button><input hidden type="file" id="import-file" accept="application/json,.json"></div>
    <div class="settings-item"><h3>Import ProZect Pack</h3><p>Add or refresh ordinary ProZects without deleting unrelated local work. Known newer Needs and Guardrails can be resolved or updated.</p><button class="ghost-btn" id="import-pack">Choose ProZect Pack</button><input hidden type="file" id="pack-file" accept="application/json,.json"></div>
    <div class="settings-item"><h3>Bootstrap existing ProZect</h3><p>Generate a provider-neutral prompt for an authoritative work/AI chat, then paste or import the returned Bootstrap Packet. StateZect previews everything before creating the ProZect.</p><div class="action-row"><button class="ghost-btn" id="bootstrap-prompt">Generate Bootstrap Prompt</button><button class="ghost-btn" id="paste-bootstrap">Paste Bootstrap Packet</button><button class="ghost-btn" id="import-bootstrap">Import Bootstrap File</button><input hidden type="file" id="bootstrap-file" accept="application/json,.json"></div></div>
    <div class="settings-item"><h3>App updates</h3><p>StateZect checks for a newer deployed shell on launch and foreground resume.</p><button class="ghost-btn" id="check-updates">Check for updates</button></div>
    <div class="settings-item danger-zone"><h3>Complete reset</h3><p>Erase all local StateZect ProZect data and return to a fresh-install state.</p><button class="danger-btn" id="reset-all">Reset StateZect</button></div>
    <div class="settings-item"><h3>About</h3><p><strong>StateZect</strong><br>A personal ProZect state tracker.<br><br>A NivareQ™ project</p></div>
  </div>`);
  app.querySelector('#how-pulse').onclick=openHowPulseWorks;
  app.querySelector('#detailed-manual').onclick=openDetailedManual;
  app.querySelectorAll('[data-theme-choice]').forEach(button=>button.onclick=()=>{applyTheme(button.dataset.themeChoice);renderSettings();});
  app.querySelector('#export').onclick=exportBackup;app.querySelector('#import').onclick=()=>app.querySelector('#import-file').click();app.querySelector('#import-file').onchange=importBackup;
  app.querySelector('#import-pack').onclick=()=>app.querySelector('#pack-file').click();app.querySelector('#pack-file').onchange=importProjectPack;
  app.querySelector('#bootstrap-prompt').onclick=openBootstrapPromptSetup;app.querySelector('#paste-bootstrap').onclick=openPasteBootstrapPacket;app.querySelector('#import-bootstrap').onclick=()=>app.querySelector('#bootstrap-file').click();app.querySelector('#bootstrap-file').onchange=importBootstrapPacketFile;
  app.querySelector('#check-updates').onclick=()=>checkForPwaUpdate({interactive:true,force:true});app.querySelector('#reset-all').onclick=openCompleteReset;
}

function historyHTML(entries,archived){
  return entries.length?entries.map(e=>`<div class="history-item"><div class="history-kind">${esc(e.kind)}${e.editedAt?'<span class="edited-marker">Edited</span>':''}</div><div class="history-summary">${esc(e.summary)}</div>${e.detail?`<div class="meta history-detail">${esc(e.detail)}</div>`:''}<div class="history-time">${esc(fmt(e.occurredAt))}</div>${!archived?`<div class="history-actions"><button class="mini" data-edit-history="${esc(e.id)}">Edit</button>${e.original?`<button class="mini" data-original-history="${esc(e.id)}">View original</button>`:''}<button class="mini" data-remove-history="${esc(e.id)}">Remove</button></div>`:''}</div>`).join(''):'<div class="meta">No updates yet.</div>';
}
async function renderProject(){
  const p=cache.projects.find(x=>x.id===selectedProjectId)||await getProject(selectedProjectId);if(!p){selectedProjectId=null;return render();}
  const needs=projectNeeds(p.id),done=completedNeeds(p.id),entries=projectEntries(p.id),removed=removedEntries(p.id),archived=p.lifecycle==='archived',next=nextNeed(p);
  shell(`<div class="detail-head"><button class="back" id="back">←</button><div><div class="meta">${esc(typeLabel(p.type))} · ${esc(p.stage)}</div><h2>${esc(p.name)}</h2></div></div>
  <div class="detail-grid two">
  <section class="panel"><h3>Current state</h3><div class="state-grid"><div class="state-item"><span>Lifecycle</span><strong>${esc(p.lifecycle)}</strong></div><div class="state-item"><span>Attention</span><strong>${esc(p.attention.replace('_',' '))}</strong></div><div class="state-item"><span>Stage</span><strong>${esc(p.stage)}</strong></div><div class="state-item"><span>Updated</span><strong>${esc(fmt(p.updatedAt))}</strong></div></div><div class="summary">${esc(p.currentSummary||'No current situation recorded.')}</div><div class="next-line"><span>Next</span> · ${esc(next?.title||'Nothing marked next')}</div>${!archived?`<div class="action-row"><button class="primary-btn" id="update-pulse">Update State</button><button class="ghost-btn" id="edit-project">Edit state</button></div>`:''}</section>
  ${p.type==='software'?`<section class="panel"><h3>Software checkpoints</h3><div class="state-item"><span>Public / released</span><strong>${esc(p.checkpoints.published||'—')}</strong></div><div class="state-item" style="margin-top:8px"><span>Accepted baseline</span><strong>${esc(p.checkpoints.accepted||'—')}</strong></div><div class="state-item" style="margin-top:8px"><span>Current candidate</span><strong>${esc(p.checkpoints.candidate||'—')}</strong></div>${p.checkpoints.candidate&&!archived?`<button class="primary-btn wide" style="margin-top:10px" id="promote">Accept current candidate</button>`:''}</section>`:''}
  <section class="panel"><div class="section-head compact"><h3>Needs</h3>${!archived?'<button class="text-btn" id="add-need">+ Need</button>':''}</div>${needs.length?needs.map(n=>`<div class="need"><div><div class="need-title">${n.id===p.nextNeedId?'→ ':''}${esc(n.title)}</div><div class="need-meta">${esc(n.state)}${n.id===p.nextNeedId?' · next':''}</div></div>${!archived?`<div class="need-actions">${n.id!==p.nextNeedId?`<button class="mini" data-nextneed="${esc(n.id)}">Next</button>`:''}<button class="mini" data-editneed="${esc(n.id)}">Edit</button><button class="mini" data-doneneed="${esc(n.id)}">Done</button></div>`:''}</div>`).join(''):'<div class="meta">Nothing open.</div>'}${done.length?`<details class="disclosure"><summary>Completed Needs · ${done.length}</summary><div class="completed-list">${done.map(n=>`<div class="need"><div><div class="need-title">${esc(n.title)}</div><div class="need-meta">done · ${esc(fmt(n.resolvedAt))}</div></div>${!archived?`<div class="need-actions"><button class="mini" data-editneed="${esc(n.id)}">Edit</button></div>`:''}</div>`).join('')}</div></details>`:''}</section>
  <section class="panel"><div class="section-head compact"><h3>Guardrails</h3>${!archived?'<button class="text-btn" id="add-guardrail">+ Guardrail</button>':''}</div>${projectGuardrails(p.id).length?projectGuardrails(p.id).map(g=>`<div class="need"><div><div class="need-title">${g.kind==='gate'?'◇ ':g.kind==='decision'?'✓ ':'▣ '}${esc(g.title)}</div><div class="need-meta">${esc(g.kind)} · ${esc(g.state)}</div></div></div>`).join(''):'<div class="meta">No standing guardrails.</div>'}</section>
  <section class="panel"><h3>ProZect Brief</h3><p class="meta">A read-only narrative generated from structured ProZect truth. Nothing new is stored.</p><div class="action-row"><button class="ghost-btn" id="quick-brief">Quick Brief</button><button class="ghost-btn" id="full-brief">Full Brief</button></div></section>
  ${!archived?`<section class="panel"><h3>ProZect handoff</h3><p class="meta">Copy a provider-neutral update prompt to the ProZect’s authoritative work/development chat, then bring the returned JSON back for validation, preview, and approval.</p><div class="action-row"><button class="ghost-btn" id="copy-update-prompt">Generate Update Prompt</button><button class="ghost-btn" id="paste-update-packet">Paste Update Packet</button><button class="ghost-btn" id="import-update-packet">Import Packet File</button><input hidden type="file" id="packet-file" accept="application/json,.json"></div></section>`:''}
  <section class="panel"><div class="section-head compact"><h3>History</h3>${removed.length?`<button class="text-btn" id="removed-history">Removed · ${removed.length}</button>`:''}</div><div class="history">${historyHTML(entries,archived)}</div></section>
  <section class="panel"><h3>ProZect lifecycle</h3>${archived?`<div class="action-row"><button class="primary-btn" id="restore">Restore ProZect</button><button class="danger-btn" id="delete">Delete permanently</button></div>`:`<p class="meta">ProZects cannot be deleted while active. Archive first.</p><button class="ghost-btn" id="archive">Archive ProZect</button>`}</section>
  </div>`);
  app.querySelector('#back').onclick=()=>{selectedProjectId=null;render();};
  app.querySelector('#update-pulse')?.addEventListener('click',()=>openQuickPulse(p));app.querySelector('#edit-project')?.addEventListener('click',()=>openEditProject(p));
  app.querySelector('#add-need')?.addEventListener('click',()=>openAddNeed(p));app.querySelector('#add-guardrail')?.addEventListener('click',()=>openAddGuardrail(p));
  app.querySelector('#promote')?.addEventListener('click',()=>acceptCandidate(p));app.querySelector('#archive')?.addEventListener('click',()=>confirmArchive(p));app.querySelector('#restore')?.addEventListener('click',()=>restore(p));app.querySelector('#delete')?.addEventListener('click',()=>openDelete(p));
  app.querySelectorAll('[data-nextneed]').forEach(b=>b.onclick=()=>markNextNeed(p,b.dataset.nextneed));app.querySelectorAll('[data-editneed]').forEach(b=>b.onclick=()=>openEditNeed(p,b.dataset.editneed));app.querySelectorAll('[data-doneneed]').forEach(b=>b.onclick=()=>confirmCompleteNeed(p,b.dataset.doneneed));
  app.querySelectorAll('[data-edit-history]').forEach(b=>b.onclick=()=>openEditHistory(p,b.dataset.editHistory));app.querySelectorAll('[data-original-history]').forEach(b=>b.onclick=()=>openOriginalHistory(b.dataset.originalHistory));app.querySelectorAll('[data-remove-history]').forEach(b=>b.onclick=()=>confirmRemoveHistory(p,b.dataset.removeHistory));
  app.querySelector('#removed-history')?.addEventListener('click',()=>openRemovedHistory(p));
  app.querySelector('#quick-brief').onclick=()=>openProjectBrief(p,'quick');app.querySelector('#full-brief').onclick=()=>openProjectBrief(p,'full');
  app.querySelector('#copy-update-prompt')?.addEventListener('click',()=>openUpdatePrompt(p));app.querySelector('#paste-update-packet')?.addEventListener('click',()=>openPasteUpdatePacket(p));app.querySelector('#import-update-packet')?.addEventListener('click',()=>app.querySelector('#packet-file').click());app.querySelector('#packet-file')?.addEventListener('change',e=>importUpdatePacketFile(e,p));
}

function openAddProject(){
  let type='general',start='new',attention='clear';
  const preset=()=>PROJECT_TYPES[type]||PROJECT_TYPES.general;
  openSheet('Add ProZect',`<form id="project-form"><div class="notice">StateZect is for any meaningful ProZect. The type only changes helpful shortcuts — it never locks the workflow.</div><button type="button" class="ghost-btn wide" id="bootstrap-existing">Bootstrap an existing ProZect from work / AI chat</button><p class="meta">Or create it manually below.</p><label>ProZect name</label><input name="name" required autocomplete="off" placeholder="What are you working on?"><label>ProZect type</label><div class="chips">${PROJECT_TYPE_ORDER.map(k=>[k,PROJECT_TYPES[k]]).map(([k,v])=>`<button type="button" class="chip ${k===type?'selected':''}" data-type="${k}">${esc(v.label)}</button>`).join('')}</div><div class="preset-note" id="type-note">${esc(preset().description)}</div><label>Starting point</label><div class="chips"><button type="button" class="chip selected" data-start="new">New ProZect</button><button type="button" class="chip" data-start="underway">Already underway</button></div><div id="dynamic"></div><label>What needs to happen next? <span class="meta">optional</span></label><div class="chips suggestion-chips" id="next-suggestions"></div><textarea data-autogrow name="next" rows="1" placeholder="One next thing"></textarea><label>Anything StateZect should protect or remember? <span class="meta">optional</span></label><textarea data-autogrow name="guardrail" rows="1" placeholder="A constraint, standing decision, or thing not to lose"></textarea><div class="form-actions"><button type="button" class="ghost-btn" data-close2>Cancel</button><button class="primary-btn">Create ProZect</button></div></form>`,sheet=>{
    const form=sheet.querySelector('#project-form'),dynamic=sheet.querySelector('#dynamic'),typeNote=sheet.querySelector('#type-note'),suggestions=sheet.querySelector('#next-suggestions');
    sheet.querySelector('#bootstrap-existing').onclick=()=>openBootstrapPromptSetup();
    const wireStage=()=>{dynamic.querySelectorAll('[data-stage]').forEach(b=>b.onclick=()=>{dynamic.querySelectorAll('[data-stage]').forEach(x=>x.classList.remove('selected'));b.classList.add('selected');form.elements.stage.value=b.dataset.stage;form.elements.customStage.value='';});dynamic.querySelector('[name="customStage"]')?.addEventListener('input',e=>{if(e.target.value.trim()){form.elements.stage.value=e.target.value.trim();dynamic.querySelectorAll('[data-stage]').forEach(x=>x.classList.remove('selected'));}});};
    const redrawSuggestions=()=>{suggestions.innerHTML=preset().nextSuggestions.map(x=>`<button type="button" class="chip suggestion" data-next-suggestion="${esc(x)}">${esc(x)}</button>`).join('');suggestions.querySelectorAll('[data-next-suggestion]').forEach(b=>b.onclick=()=>{form.elements.next.value=b.dataset.nextSuggestion;autoGrow(form.elements.next);suggestions.querySelectorAll('.chip').forEach(x=>x.classList.toggle('selected',x===b));});};
    const redraw=()=>{const stages=preset().stages;dynamic.innerHTML=`<label>Current stage</label><div class="chips">${stages.map((st,i)=>`<button type="button" class="chip ${i===0?'selected':''}" data-stage="${esc(st)}">${esc(st)}</button>`).join('')}</div><input type="hidden" name="stage" value="${esc(stages[0])}"><label class="compact-label">Or use your own stage <span class="meta">optional</span></label><input name="customStage" autocomplete="off" placeholder="Custom stage">${start==='underway'?`<label>Current situation <span class="meta">optional</span></label><textarea data-autogrow name="current" rows="2" placeholder="Where does this ProZect stand right now?"></textarea><label>Attention</label><div class="chips">${[['clear','Clear'],['needs_attention','Needs attention'],['blocked','Blocked'],['waiting','Waiting']].map(([k,l])=>`<button type="button" class="chip ${k===attention?'selected':''}" data-start-attention="${k}">${l}</button>`).join('')}</div><input type="hidden" name="attention" value="${attention}"><label>One important past milestone <span class="meta">optional</span></label><textarea data-autogrow name="milestone" rows="1" placeholder="A useful milestone, not a full reconstruction of the past"></textarea>${type==='software'?`<label>Accepted baseline <span class="meta">optional</span></label><input name="accepted" placeholder="e.g. Build 12"><label>Current candidate <span class="meta">optional</span></label><input name="candidate" placeholder="e.g. Build 13 Beta">`:''}`:''}`;wireStage();dynamic.querySelectorAll('[data-start-attention]').forEach(b=>b.onclick=()=>{attention=b.dataset.startAttention;dynamic.querySelectorAll('[data-start-attention]').forEach(x=>x.classList.toggle('selected',x===b));form.elements.attention.value=attention;});wireAutoGrow(dynamic);redrawSuggestions();typeNote.textContent=preset().description;};
    redraw();sheet.querySelectorAll('[data-type]').forEach(b=>b.onclick=()=>{type=b.dataset.type;sheet.querySelectorAll('[data-type]').forEach(x=>x.classList.toggle('selected',x===b));redraw();});sheet.querySelectorAll('[data-start]').forEach(b=>b.onclick=()=>{start=b.dataset.start;sheet.querySelectorAll('[data-start]').forEach(x=>x.classList.toggle('selected',x===b));redraw();});sheet.querySelector('[data-close2]').onclick=closeModal;
    form.onsubmit=async e=>{e.preventDefault();const f=new FormData(form);const timestamp=new Date().toISOString();const stage=String(f.get('customStage')||'').trim()||f.get('stage');const initialSummary=String(f.get('current')||'').trim()||(start==='new'?`${preset().label} ProZect started`:'Existing ProZect added to StateZect');let project=createProject({name:f.get('name'),type,stage,attention:f.get('attention')||'clear',currentSummary:initialSummary,checkpoints:{accepted:f.get('accepted'),candidate:f.get('candidate')}},timestamp);const initial=applyPulseUpdate(project,{kind:start==='new'?'ProZect created':'Existing ProZect added',summary:start==='new'?'ProZect created in StateZect':'Existing ProZect snapshot added to StateZect',stage,attention:f.get('attention')||'clear',currentSummary:initialSummary},timestamp);project=initial.project;const entries=[initial.entry];const milestone=String(f.get('milestone')||'').trim();if(milestone)entries.push(createPulseEntry(project.id,{kind:'Past milestone',summary:milestone,occurredAt:timestamp},timestamp));let needs=[];const nextText=String(f.get('next')||'').trim();if(nextText){const n=createNeed(project.id,{title:nextText},timestamp);const rel=setProjectNext(project,[n],n.id,timestamp);project=rel.project;needs=rel.needs;}const guardText=String(f.get('guardrail')||'').trim();const guardrails=guardText?[createGuardrail(project.id,{title:guardText,kind:'protect'},timestamp)]:[];if(guardrails.length)project=bumpProjectRevision(project,timestamp);await saveProjectBootstrap(project,entries,needs,guardrails);closeModal();await refresh();view='pulse';selectedProjectId=null;render();toast('ProZect added to StateZect');};
  });
}
function openQuickPulse(p){
  let kind=PROJECT_TYPES[p.type]?.quickUpdates?.[0]||'Progress made';const stageOptions=PROJECT_TYPES[p.type]?.stages||PROJECT_TYPES.general.stages;const currentNext=nextNeed(p)?.title||'';
  const generated=()=>{const subject=p.checkpoints?.candidate||p.checkpoints?.accepted||p.name;const common={'Waiting':`${p.name} is waiting`,'Resumed':`${p.name} resumed`,'Problem found':`Problem found in ${p.name}`,'Decision made':`Decision made for ${p.name}`,'Milestone reached':`${p.name} reached a milestone`};const maps={software:{'Automated checks passed':`${subject} passed automated checks`,'Real-device pass':`${subject} passed real-device testing`,'Real-device fail':`${subject} needs another correction after real-device testing`,'Accepted baseline':`${subject} accepted as the current baseline`,'Public release':`${subject} released`,'Bug found':`Issue found in ${p.name}`,'Bug fixed':`Issue fixed in ${p.name}`,'Gate opened':'A ProZect gate was opened','Gate closed':'A ProZect gate was closed'},writing:{'Draft progress':`Drafting progressed in ${p.name}`,'Section / chapter complete':`A section or chapter was completed in ${p.name}`,'Research found':`Useful research was added to ${p.name}`,'Revision complete':`A revision pass was completed in ${p.name}`,'Feedback received':`Feedback was received for ${p.name}`},film:{'Script progress':`Script work progressed in ${p.name}`,'Pre-production progress':`Pre-production progressed in ${p.name}`,'Shoot progress':`Production progressed in ${p.name}`,'Edit progress':`Editing progressed in ${p.name}`,'Review / feedback':`Review or feedback was recorded for ${p.name}`},making:{'Materials acquired':`Materials were acquired for ${p.name}`,'Part completed':`A part was completed for ${p.name}`,'Assembly progress':`Assembly progressed in ${p.name}`,'Design changed':`The design changed for ${p.name}`},research:{'Source found':`A useful source was found for ${p.name}`,'Finding recorded':`A finding was recorded for ${p.name}`,'Research progress':`Research progressed in ${p.name}`,'Synthesis progress':`Synthesis progressed in ${p.name}`,'Draft progress':`Drafting progressed in ${p.name}`},general:{'Progress made':`Progress was made on ${p.name}`}};return maps[p.type]?.[kind]||common[kind]||kind;};
  openSheet('Update State',`<form id="pulse-form"><div class="notice">Choose what happened first. Most updates need selections plus only the new wording.</div><label>What happened?</label><div class="chips">${PROJECT_TYPES[p.type].quickUpdates.map((k,i)=>`<button type="button" class="chip ${i===0?'selected':''}" data-kind="${esc(k)}">${esc(k)}</button>`).join('')}</div><label>Stage</label><div class="chips" id="update-stage-chips">${stageOptions.map(st=>`<button type="button" class="chip ${st===p.stage?'selected':''}" data-update-stage="${esc(st)}">${esc(st)}</button>`).join('')}</div><input name="stage" value="${esc(p.stage)}" placeholder="Or type your own stage"><label>Attention</label><div class="chips">${[['clear','Clear'],['needs_attention','Needs attention'],['blocked','Blocked'],['waiting','Waiting']].map(([k,l])=>`<button type="button" class="chip ${k===p.attention?'selected':''}" data-attention="${k}">${l}</button>`).join('')}</div><input type="hidden" name="attention" value="${esc(p.attention)}"><div id="kind-extra"></div><label>Current situation <span class="meta">optional — generated if blank</span></label><textarea data-autogrow name="summary" rows="2" placeholder="${esc(generated())}"></textarea><label>Next Need <span class="meta">clear to leave nothing marked Next</span></label><textarea data-autogrow name="next" rows="1">${esc(currentNext)}</textarea><div class="form-actions"><button type="button" class="ghost-btn" data-close2>Cancel</button><button class="primary-btn">Save update</button></div></form>`,sheet=>{
    const form=sheet.querySelector('#pulse-form'),extra=sheet.querySelector('#kind-extra');sheet.querySelectorAll('[data-update-stage]').forEach(b=>b.onclick=()=>{sheet.querySelectorAll('[data-update-stage]').forEach(x=>x.classList.toggle('selected',x===b));form.elements.stage.value=b.dataset.updateStage;});form.elements.stage.addEventListener('input',()=>sheet.querySelectorAll('[data-update-stage]').forEach(x=>x.classList.toggle('selected',x.dataset.updateStage===form.elements.stage.value.trim())));const redrawExtra=()=>{extra.innerHTML=(p.type==='software'&&kind==='Candidate created')?`<label>Candidate label</label><input name="candidate" required placeholder="Build / version label">`:(p.type==='software'&&kind==='Public release')?`<label>Release label <span class="meta">blank uses accepted baseline</span></label><input name="published" placeholder="${esc(p.checkpoints.accepted||'Release label')}">`:'';form.elements.summary.placeholder=generated();};redrawExtra();
    sheet.querySelectorAll('[data-kind]').forEach(b=>b.onclick=()=>{kind=b.dataset.kind;sheet.querySelectorAll('[data-kind]').forEach(x=>x.classList.remove('selected'));b.classList.add('selected');redrawExtra();});sheet.querySelectorAll('[data-attention]').forEach(b=>b.onclick=()=>{sheet.querySelectorAll('[data-attention]').forEach(x=>x.classList.remove('selected'));b.classList.add('selected');form.elements.attention.value=b.dataset.attention;});sheet.querySelector('[data-close2]').onclick=closeModal;
    form.onsubmit=async e=>{e.preventDefault();const f=new FormData(form);let attention=f.get('attention'),lifecycle=p.lifecycle,summary=String(f.get('summary')||'').trim()||generated(),checkpoints={};if(kind==='Real-device fail'||kind==='Bug found')attention='needs_attention';if(kind==='Waiting')attention='waiting';if(kind==='Resumed'){attention='clear';lifecycle='active';}if(kind==='Candidate created')checkpoints.candidate=f.get('candidate');if(kind==='Public release')checkpoints.published=f.get('published')||p.checkpoints.accepted;
      let result;if(kind==='Accepted baseline'&&p.checkpoints.candidate){result=promoteCandidate(p);result.entry.summary=summary;result.project.stage=f.get('stage');result.project.attention=attention;}else result=applyPulseUpdate(p,{kind,summary,stage:f.get('stage'),attention,lifecycle,currentSummary:summary,checkpoints});
      let project=result.project;let own=allProjectNeeds(p.id).map(n=>({...n}));const nextText=String(f.get('next')||'').trim();if(nextText!==currentNext){let chosen=nextText?own.find(n=>n.state!=='done'&&n.title===nextText):null;if(nextText&&!chosen){chosen=createNeed(p.id,{title:nextText});own.push(chosen);}const rel=setProjectNext(project,own,chosen?.id||null);project=rel.project;own=rel.needs;}await savePulseAndNeeds(project,result.entry,own);closeModal();await refresh();renderProject();toast('State updated');};
  });
}

function openEditProject(p){
  openSheet('Edit ProZect state',`<form id="edit-form"><label>Stage</label><input name="stage" list="edit-stage-options" value="${esc(p.stage)}"><datalist id="edit-stage-options">${PROJECT_TYPES[p.type].stages.map(st=>`<option value="${esc(st)}"></option>`).join('')}</datalist><label>Lifecycle</label><select name="lifecycle"><option value="active" ${p.lifecycle==='active'?'selected':''}>Active</option><option value="paused" ${p.lifecycle==='paused'?'selected':''}>Paused</option><option value="completed" ${p.lifecycle==='completed'?'selected':''}>Completed</option></select><label>Attention</label><select name="attention"><option value="clear" ${p.attention==='clear'?'selected':''}>Clear</option><option value="needs_attention" ${p.attention==='needs_attention'?'selected':''}>Needs attention</option><option value="blocked" ${p.attention==='blocked'?'selected':''}>Blocked</option><option value="waiting" ${p.attention==='waiting'?'selected':''}>Waiting</option></select><label>Current situation</label><textarea data-autogrow name="current" rows="2">${esc(p.currentSummary)}</textarea>${p.type==='software'?`<label>Public / released checkpoint</label><input name="published" value="${esc(p.checkpoints.published)}"><label>Accepted baseline</label><input name="accepted" value="${esc(p.checkpoints.accepted)}"><label>Current candidate</label><input name="candidate" value="${esc(p.checkpoints.candidate)}">`:''}<div class="notice">Next is managed from Needs so the dashboard and ProZect detail always share one authoritative Next relationship.</div><div class="form-actions"><button type="button" class="ghost-btn" data-close2>Cancel</button><button class="primary-btn">Save state</button></div></form>`,sheet=>{const form=sheet.querySelector('#edit-form');sheet.querySelector('[data-close2]').onclick=closeModal;form.onsubmit=async e=>{e.preventDefault();const f=new FormData(form);const result=applyPulseUpdate(p,{kind:'State edited',summary:'ProZect state updated',stage:f.get('stage'),lifecycle:f.get('lifecycle'),attention:f.get('attention'),currentSummary:f.get('current'),checkpoints:p.type==='software'?{published:f.get('published'),accepted:f.get('accepted'),candidate:f.get('candidate')}:undefined});await savePulse(result.project,result.entry);closeModal();await refresh();renderProject();};});
}

function openAddNeed(p){openSheet('Add need',`<form id="need-form"><label>What does this ProZect need?</label><textarea data-autogrow name="title" rows="2" required autofocus placeholder="One clear need"></textarea><label><input style="width:auto" type="checkbox" name="next" checked> Make this the next thing</label><div class="form-actions"><button type="button" class="ghost-btn" data-close2>Cancel</button><button class="primary-btn">Add need</button></div></form>`,sheet=>{const f=sheet.querySelector('form');sheet.querySelector('[data-close2]').onclick=closeModal;f.onsubmit=async e=>{e.preventDefault();const data=new FormData(f);const newNeed=createNeed(p.id,{title:data.get('title')});let project=bumpProjectRevision(p);let rows=[...allProjectNeeds(p.id),newNeed];if(data.get('next')){const rel=setProjectNext(project,rows,newNeed.id);project=rel.project;rows=rel.needs;}await saveProjectAndNeeds(project,rows);closeModal();await refresh();renderProject();};});}
function openEditNeed(p,needId){const need=cache.needs.find(n=>n.id===needId&&n.projectId===p.id);if(!need)return;openSheet('Edit Need',`<form id="edit-need-form"><div class="notice">Fix wording or spelling here. Editing a Need does not rewrite History.</div><label>Need</label><textarea data-autogrow name="title" rows="2" required>${esc(need.title)}</textarea><div class="form-actions"><button type="button" class="ghost-btn" data-close2>Cancel</button><button class="primary-btn">Save changes</button></div><button type="button" class="danger-btn wide" id="remove-need" style="margin-top:12px">Remove Need</button></form>`,sheet=>{const form=sheet.querySelector('#edit-need-form');sheet.querySelector('[data-close2]').onclick=closeModal;form.onsubmit=async e=>{e.preventDefault();const title=String(new FormData(form).get('title')||'').trim();if(!title){alert('Need wording cannot be empty.');return;}const updated=updateNeed(need,{title});let rows=allProjectNeeds(p.id).map(n=>n.id===need.id?updated:n),project;if(p.nextNeedId===need.id||need.isNext){const rel=setProjectNext(p,rows,need.id);project=rel.project;rows=rel.needs;}else project=bumpProjectRevision(p);await saveProjectAndNeeds(project,rows);closeModal();await refresh();renderProject();toast('Need updated');};sheet.querySelector('#remove-need').onclick=()=>confirmRemoveNeed(p,need.id);});}
function confirmRemoveNeed(p,needId){const need=cache.needs.find(n=>n.id===needId&&n.projectId===p.id);if(!need)return;openSheet('Remove Need?',`<p class="notice">This removes the Need completely. It does not remove or rewrite ProZect History.${p.nextNeedId===need.id||need.isNext?' Because this is the current Next, Next will be cleared.':''}</p><div class="need-title">${esc(need.title)}</div><div class="form-actions"><button class="ghost-btn" data-close2>Cancel</button><button class="danger-btn" id="confirm-remove-need">Remove Need</button></div>`,sheet=>{sheet.querySelector('[data-close2]').onclick=closeModal;sheet.querySelector('#confirm-remove-need').onclick=async()=>{let rows=allProjectNeeds(p.id).filter(n=>n.id!==need.id),project;if(p.nextNeedId===need.id||need.isNext){const rel=setProjectNext(p,rows,null);project=rel.project;rows=rel.needs;}else project=bumpProjectRevision(p);await deleteNeedAndSaveProject(project,need.id,rows);closeModal();await refresh();renderProject();toast('Need removed');};});}
function openAddGuardrail(p){let kind='protect';openSheet('Add guardrail',`<form id="guard-form"><label>What should stay explicit?</label><textarea data-autogrow name="title" rows="2" required autofocus placeholder="e.g. Keep accepted bottom shell unchanged"></textarea><label>Kind</label><div class="chips"><button type="button" class="chip selected" data-kind="protect">Protect</button><button type="button" class="chip" data-kind="gate">Gate</button><button type="button" class="chip" data-kind="decision">Decision</button></div><div id="guard-state"></div><div class="form-actions"><button type="button" class="ghost-btn" data-close2>Cancel</button><button class="primary-btn">Add guardrail</button></div></form>`,sheet=>{const form=sheet.querySelector('form'),stateBox=sheet.querySelector('#guard-state');const redraw=()=>{stateBox.innerHTML=kind==='gate'?'<label>Gate state</label><select name="state"><option value="closed">Closed</option><option value="open">Open</option></select>':'<input type="hidden" name="state" value="active">';};redraw();sheet.querySelectorAll('[data-kind]').forEach(b=>b.onclick=()=>{kind=b.dataset.kind;sheet.querySelectorAll('[data-kind]').forEach(x=>x.classList.remove('selected'));b.classList.add('selected');redraw();});sheet.querySelector('[data-close2]').onclick=closeModal;form.onsubmit=async e=>{e.preventDefault();const f=new FormData(form);const guard=createGuardrail(p.id,{title:f.get('title'),kind,state:f.get('state')});await saveProjectAndGuardrail(bumpProjectRevision(p),guard);closeModal();await refresh();renderProject();};});}

async function markNextNeed(p,needId){const rel=setProjectNext(p,allProjectNeeds(p.id),needId);await saveProjectAndNeeds(rel.project,rel.needs);await refresh();renderProject();toast('Next updated');}
function confirmCompleteNeed(p,needId){const n=cache.needs.find(x=>x.id===needId);if(!n)return;openSheet('Mark Need as done?',`<p class="notice">${esc(n.title)}</p><p class="meta">Done Needs stay available in Completed Needs. Nothing is deleted.</p><div class="form-actions"><button class="ghost-btn" data-close2>Cancel</button><button class="primary-btn" id="confirm-done">Mark done</button></div>`,sheet=>{sheet.querySelector('[data-close2]').onclick=closeModal;sheet.querySelector('#confirm-done').onclick=async()=>{let rows=allProjectNeeds(p.id).map(x=>x.id===n.id?updateNeed(x,{state:'done',isNext:false}):x);let project=bumpProjectRevision(p);const wasNext=p.nextNeedId===n.id||n.isNext;if(wasNext){const rel=setProjectNext(project,rows,null);project=rel.project;rows=rel.needs;}await saveProjectAndNeeds(project,rows);closeModal();await refresh();renderProject();if(wasNext&&projectNeeds(p.id).length)openChooseNext(project);else toast('Need completed');};});}
function openChooseNext(p){const rows=projectNeeds(p.id);openSheet('Choose the next thing',`<p class="notice">The completed Need was Next. Choose another open Need, or leave Next empty for now.</p><div class="choice-list">${rows.map(n=>`<button class="choice-row" data-choose-next="${esc(n.id)}">${esc(n.title)}</button>`).join('')}</div><button class="ghost-btn wide" id="no-next" style="margin-top:12px">Not now</button>`,sheet=>{sheet.querySelectorAll('[data-choose-next]').forEach(b=>b.onclick=async()=>{const current=cache.projects.find(x=>x.id===p.id)||p;const rel=setProjectNext(current,allProjectNeeds(p.id),b.dataset.chooseNext);await saveProjectAndNeeds(rel.project,rel.needs);closeModal();await refresh();renderProject();toast('Next updated');});sheet.querySelector('#no-next').onclick=()=>{closeModal();toast('Need completed');};});}

function openEditHistory(p,entryId){const entry=cache.pulseEntries.find(e=>e.id===entryId);if(!entry)return;openSheet('Edit History',`<form id="history-edit"><div class="notice">Corrections keep the original version. The normal history shows the corrected text with an Edited marker.</div><label>Kind</label><input name="kind" value="${esc(entry.kind)}"><label>Summary</label><textarea data-autogrow name="summary" rows="2" required>${esc(entry.summary)}</textarea><label>Detail <span class="meta">optional</span></label><textarea data-autogrow name="detail" rows="2">${esc(entry.detail||'')}</textarea><div class="form-actions"><button type="button" class="ghost-btn" data-close2>Cancel</button><button class="primary-btn">Save correction</button></div></form>`,sheet=>{sheet.querySelector('[data-close2]').onclick=closeModal;sheet.querySelector('form').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.currentTarget);const edited=editPulseEntry(entry,{kind:f.get('kind'),summary:f.get('summary'),detail:f.get('detail')});await savePulse(bumpProjectRevision(p),edited);closeModal();await refresh();renderProject();toast('History corrected');};});}
function openOriginalHistory(entryId){const entry=cache.pulseEntries.find(e=>e.id===entryId);if(!entry?.original)return;openSheet('Original history entry',`<div class="original-box"><div class="history-kind">${esc(entry.original.kind)}</div><div class="history-summary">${esc(entry.original.summary)}</div>${entry.original.detail?`<div class="meta history-detail">${esc(entry.original.detail)}</div>`:''}</div><p class="meta">Current corrected version remains in History.</p>`);}
function confirmRemoveHistory(p,entryId){const entry=cache.pulseEntries.find(e=>e.id===entryId);if(!entry)return;openSheet('Remove from history?',`<p class="notice">This hides the entry from normal History, ProZect Briefs, and summaries. It can be restored from Removed Entries.</p><div class="history-summary">${esc(entry.summary)}</div><div class="form-actions"><button class="ghost-btn" data-close2>Cancel</button><button class="danger-btn" id="confirm-remove">Remove</button></div>`,sheet=>{sheet.querySelector('[data-close2]').onclick=closeModal;sheet.querySelector('#confirm-remove').onclick=async()=>{await savePulse(bumpProjectRevision(p),removePulseEntry(entry));closeModal();await refresh();renderProject();toast('Moved to Removed Entries');};});}
function openRemovedHistory(p){const rows=removedEntries(p.id);openSheet('Removed Entries',`<p class="notice">These entries are excluded from normal history and ProZect Briefs but are still recoverable.</p><div class="removed-list">${rows.map(e=>`<div class="removed-row"><div><div class="history-kind">${esc(e.kind)}</div><div class="history-summary">${esc(e.summary)}</div><div class="history-time">Removed ${esc(fmt(e.removedAt))}</div></div><div class="need-actions"><button class="mini" data-restore-history="${esc(e.id)}">Restore</button><button class="mini danger-mini" data-erase-history="${esc(e.id)}">Erase</button></div></div>`).join('')||'<div class="meta">Nothing removed.</div>'}</div>`,sheet=>{sheet.querySelectorAll('[data-restore-history]').forEach(b=>b.onclick=async()=>{const entry=cache.pulseEntries.find(e=>e.id===b.dataset.restoreHistory);await savePulse(bumpProjectRevision(p),restorePulseEntry(entry));closeModal();await refresh();renderProject();toast('History restored');});sheet.querySelectorAll('[data-erase-history]').forEach(b=>b.onclick=()=>openPermanentHistoryErase(p,b.dataset.eraseHistory));});}
function openPermanentHistoryErase(p,entryId){const entry=cache.pulseEntries.find(e=>e.id===entryId);if(!entry)return;openSheet('Permanently erase entry?',`<p class="notice danger-notice"><strong>This cannot be restored inside StateZect.</strong><br><br>${esc(entry.summary)}</p><label><input style="width:auto" id="erase-check" type="checkbox"> I understand this permanently destroys this history entry</label><label>Type <strong>ERASE</strong></label><input id="erase-word" autocomplete="off" placeholder="ERASE"><button class="danger-btn wide" id="erase-final" style="margin-top:16px">Erase permanently</button>`,sheet=>{sheet.querySelector('#erase-final').onclick=async()=>{if(!sheet.querySelector('#erase-check').checked||sheet.querySelector('#erase-word').value.trim()!=='ERASE'){alert('Permanent erase confirmation is incomplete.');return;}await deletePulseEntryAndSaveProject(bumpProjectRevision(p),entry.id);closeModal();await refresh();renderProject();toast('History entry permanently erased');};});}

function openProjectBrief(p,mode){const text=buildProjectBrief(p,cache.pulseEntries.filter(e=>e.projectId===p.id),allProjectNeeds(p.id),cache.guardrails.filter(g=>g.projectId===p.id),mode);const title=mode==='full'?'Full ProZect Brief':'Quick Brief';openSheet(title,`<textarea class="brief-box" data-autogrow readonly>${esc(text)}</textarea><div class="action-row"><button class="primary-btn" id="copy-brief">Copy Brief</button><button class="ghost-btn" id="share-brief">Share</button></div>`,sheet=>{sheet.querySelector('#copy-brief').onclick=()=>copyText(text,'ProZect Brief copied');sheet.querySelector('#share-brief').onclick=()=>shareText(`${p.name} — ${title}`,text);});}
function openUpdatePrompt(p){const prompt=makeProjectUpdatePrompt(p,projectEntries(p.id),allProjectNeeds(p.id),cache.guardrails.filter(g=>g.projectId===p.id));openSheet('ProZect Update Prompt',`<div class="notice">Copy this into the ProZect’s authoritative development/work chat. Ask that chat to return only the requested JSON packet.</div><textarea class="prompt-box" data-autogrow readonly>${esc(prompt)}</textarea><button class="primary-btn wide" id="copy-prompt" style="margin-top:12px">Copy Update Prompt</button>`,sheet=>{sheet.querySelector('#copy-prompt').onclick=()=>copyText(prompt,'Update Prompt copied');});}
function openPasteUpdatePacket(p){openSheet('Paste Update Packet',`<div class="notice">Paste the JSON returned by the ProZect/work chat. StateZect validates it before showing a preview. Nothing is applied yet.</div><textarea data-autogrow id="packet-json" rows="8" placeholder="{ ... }"></textarea><button class="primary-btn wide" id="review-packet" style="margin-top:12px">Review packet</button>`,sheet=>{sheet.querySelector('#review-packet').onclick=async()=>{try{const parsed=parseProjectUpdatePacketText(sheet.querySelector('#packet-json').value);await reviewUpdatePacket(p,parsed.data,{repairs:parsed.repairs});}catch(err){alert(err.message||'That packet is not valid JSON.');}};});}
async function importUpdatePacketFile(e,p){const file=e.target.files?.[0];if(!file)return;try{const parsed=parseProjectUpdatePacketText(await file.text());await reviewUpdatePacket(p,parsed.data,{repairs:parsed.repairs});}catch(err){alert(err.message||'That file is not a valid Update Packet.');}finally{e.target.value='';}}
async function reviewUpdatePacket(p,data,{repairs=[]}={}){const packet=validateProjectUpdatePacket(data);if(await isPacketApplied(packet.packetId))throw new Error('This Update Packet has already been applied.');const preview=previewProjectUpdatePacket(packet,p,allProjectNeeds(p.id),cache.guardrails.filter(g=>g.projectId===p.id));const needMap=Object.fromEntries(allProjectNeeds(p.id).map(n=>[n.id,n.title]));const guardMap=Object.fromEntries(cache.guardrails.filter(g=>g.projectId===p.id).map(g=>[g.id,g.title]));const details=[...preview.lines,...packet.changes.needs.resolve.map(id=>`Resolve Need: ${needMap[id]||id}`),...packet.changes.needs.upsert.map(n=>`Need: ${n.title} [${n.state||'open'}]`),...packet.changes.guardrails.retire.map(id=>`Retire Guardrail: ${guardMap[id]||id}`),...packet.changes.guardrails.upsert.map(g=>`Guardrail: ${g.title} [${g.state||g.kind||'active'}]`),...packet.changes.pulseEntries.map(e=>`History: ${e.summary}`)];openSheet('Preview ProZect Update',`${preview.stale?`<div class="notice danger-notice"><strong>Older base state.</strong><br>This packet was prepared from revision ${packet.basedOnRevision}; ${esc(p.name)} is now revision ${preview.currentRevision}. Review carefully before overriding the stale-state warning.</div>`:'<div class="notice">Validated against the current ProZect revision. No database changes have been made yet.</div>'}${repairs.length?'<div class="notice"><strong>Formatting repaired before validation.</strong><br>StateZect normalized harmless AI-output formatting such as a Markdown code fence or smart/curly JSON quotation marks. The strict Update Packet schema still passed before this preview.</div>':''}<div class="preview-list">${details.map(line=>`<div class="preview-row">${esc(line)}</div>`).join('')}</div>${preview.stale?'<label><input style="width:auto" id="stale-ok" type="checkbox"> I reviewed this older packet and still want to apply it</label>':''}<button class="primary-btn wide" id="apply-packet" style="margin-top:16px">Apply Update</button>`,sheet=>{sheet.querySelector('#apply-packet').onclick=async()=>{try{const allowStale=preview.stale&&sheet.querySelector('#stale-ok')?.checked;if(preview.stale&&!allowStale){alert('Review and acknowledge the stale packet before applying.');return;}const result=await applyProjectUpdatePacket(packet,{allowStale});closeModal();await refresh();renderProject();toast(result.stale?'Stale packet applied after review':'ProZect update applied');}catch(err){alert(err.message);}};});}

function openBootstrapPromptSetup(){
  let type='general';
  openSheet('Bootstrap existing ProZect',`<div class="notice">Use this when a ProZect already has useful context in an authoritative work/development/AI chat. StateZect generates the stable ProZect ID and packet contract; the returned packet is previewed before anything is created.</div><label>ProZect type</label><div class="chips">${PROJECT_TYPE_ORDER.map(k=>`<button type="button" class="chip ${k===type?'selected':''}" data-bootstrap-type="${k}">${esc(PROJECT_TYPES[k].label)}</button>`).join('')}</div><label>ProZect name <span class="meta">optional, but helpful when known</span></label><input id="bootstrap-name" autocomplete="off" placeholder="Leave blank if the work chat should identify it"><button class="primary-btn wide" id="generate-bootstrap" style="margin-top:14px">Generate Bootstrap Prompt</button>`,sheet=>{
    sheet.querySelectorAll('[data-bootstrap-type]').forEach(b=>b.onclick=()=>{type=b.dataset.bootstrapType;sheet.querySelectorAll('[data-bootstrap-type]').forEach(x=>x.classList.toggle('selected',x===b));});
    sheet.querySelector('#generate-bootstrap').onclick=()=>{const projectId=`project_${crypto.randomUUID()}`;const prompt=makeProjectBootstrapPrompt({projectId,type,name:sheet.querySelector('#bootstrap-name').value});openSheet('ProZect Bootstrap Prompt',`<div class="notice">Copy this into the ProZect’s authoritative work/development chat. The returned JSON can later be pasted from More → Bootstrap existing ProZect; StateZect does not need this sheet to remain open.</div><textarea class="prompt-box" data-autogrow readonly>${esc(prompt)}</textarea><button class="primary-btn wide" id="copy-bootstrap-prompt" style="margin-top:12px">Copy Bootstrap Prompt</button>`,promptSheet=>{promptSheet.querySelector('#copy-bootstrap-prompt').onclick=()=>copyText(prompt,'Bootstrap Prompt copied');});};
  });
}
function openPasteBootstrapPacket(){openSheet('Paste Bootstrap Packet',`<div class="notice">Paste the JSON returned by the authoritative ProZect/work chat. StateZect validates and previews it before creating anything.</div><textarea data-autogrow id="bootstrap-json" rows="8" placeholder="{ ... }"></textarea><button class="primary-btn wide" id="review-bootstrap" style="margin-top:12px">Review packet</button>`,sheet=>{sheet.querySelector('#review-bootstrap').onclick=async()=>{try{const parsed=parseProjectBootstrapPacketText(sheet.querySelector('#bootstrap-json').value);await reviewBootstrapPacket(parsed.data,{repairs:parsed.repairs});}catch(err){alert(err.message||'That packet is not valid JSON.');}};});}
async function importBootstrapPacketFile(e){const file=e.target.files?.[0];if(!file)return;try{const parsed=parseProjectBootstrapPacketText(await file.text());await reviewBootstrapPacket(parsed.data,{repairs:parsed.repairs});}catch(err){alert(err.message||'That file is not a valid Bootstrap Packet.');}finally{e.target.value='';}}
async function reviewBootstrapPacket(data,{repairs=[]}={}){const packet=validateProjectBootstrapPacket(data);if(await isPacketApplied(packet.packetId))throw new Error('This Bootstrap Packet has already been applied.');if(cache.projects.some(p=>p.id===packet.project.id))throw new Error('A ProZect with this stable ProZect ID already exists in StateZect.');const preview=previewProjectBootstrapPacket(packet);const details=[...preview.lines,...packet.pulseEntries.map(e=>`History: ${e.summary}`),...packet.needs.map(n=>`Need: ${n.title} [${n.state}]`),...packet.guardrails.map(g=>`Guardrail: ${g.title} [${g.state}]`)];openSheet('Preview ProZect Bootstrap',`<div class="notice">Validated. No ProZect has been created yet.</div>${repairs.length?'<div class="notice"><strong>Formatting repaired before validation.</strong><br>StateZect normalized harmless AI-output formatting before strict Bootstrap Packet validation.</div>':''}<div class="preview-list">${details.map(line=>`<div class="preview-row">${esc(line)}</div>`).join('')}</div><button class="primary-btn wide" id="apply-bootstrap" style="margin-top:16px">Create ProZect</button>`,sheet=>{sheet.querySelector('#apply-bootstrap').onclick=async()=>{try{const result=await applyProjectBootstrapPacket(packet);closeModal();await refresh();view='pulse';selectedProjectId=result.project.id;await renderProject();toast('ProZect bootstrapped into StateZect');}catch(err){alert(err.message);}};});}

function openHowPulseWorks(){openSheet('How StateZect Works',`<div class="guide"><h3>ProZect types</h3><p>Software, Writing, Film / Video, Making / Workshop, Research, and General all use the same ProZect truth model. Type presets only provide useful stages, update choices, and Next suggestions; custom stages are always allowed.</p><h3>Starting a ProZect</h3><p>Choose New ProZect for a clean start, Already underway to capture the present without reconstructing the entire past, or Bootstrap an existing ProZect when an authoritative work/AI chat can return a structured snapshot. Bootstrap always previews before creation.</p><h3>ProZect</h3><p>The current snapshot: stage, lifecycle, attention, current situation, checkpoints, and one authoritative Next Need.</p><h3>Update State</h3><p>Record what changed. StateZect keeps the current snapshot and historical entry separate.</p><h3>Needs & Next</h3><p>Needs are lightweight things the ProZect requires. One open Need can be Next. Done keeps it in Completed Needs. Edit fixes wording; Remove cleans up test/junk/obsolete Needs after confirmation.</p><h3>Guardrails</h3><p>Things that must remain explicit: protected behavior, gates, or standing decisions.</p><h3>History hygiene</h3><p>Edit mistakes with an Edited marker and View Original. Remove test/junk entries into recoverable Removed Entries; permanent erase is deliberately harder.</p><h3>ProZect Brief</h3><p>Quick and Full Briefs turn structured truth into readable text for scanning or sharing. Briefs are generated, not stored as a competing truth.</p><h3>ProZect handoff</h3><p>Existing ProZects use Update Prompt → Update Packet → Preview → Apply. ProZects that already exist outside StateZect can use Bootstrap Prompt → Bootstrap Packet → Preview → Create. Both paths are provider-neutral and accept paste or JSON-file transport.</p><h3>ProZect Pack vs Backup</h3><p>ProZect Packs merge/refresh ProZects. Full Backup restore replaces the entire local StateZect database.</p><h3>Archive</h3><p>ProZects must be archived before permanent deletion. Archive is reversible until deletion is explicitly confirmed.</p></div>`);}

function openDetailedManual(){openSheet('Detailed Manual',`<div class="manual"><div class="manual-intro"><strong>Start here if StateZect is completely new to you.</strong><p>You do not need to understand databases, JSON, software development, or ProZect-management terminology to use StateZect. StateZect has one job: help you remember what each ProZect is, where it stands now, what happened, what needs attention next, and what must not be forgotten.</p><p><strong>Safest rule:</strong> if you are unsure about a destructive action, stop. Export a backup first. ProZect Packs and Update/Bootstrap Packets are normally non-destructive; Full Backup restore, permanent deletion, and Complete Reset are intentionally different.</p></div>

<details class="manual-section" open><summary>1. What StateZect is — and what it is not</summary><div class="manual-body"><p>StateZect is a personal ProZect-state tracker. A ProZect can be software, a writing ProZect, woodworking, a film, research, or anything else that has a meaningful state over time.</p><p>StateZect is not meant to replace a full task manager, calendar, Kanban board, file-storage service, or team-management system. Keep the important ProZect truth here; do not feel obligated to turn every tiny action into a Need.</p><div class="manual-example"><strong>Example</strong><br>ProZect: Dining Table<br>Current situation: Base is assembled; tabletop is unfinished.<br>Next: Sand tabletop.<br>Need: Buy 220-grit paper.<br>Guardrail: Do not reduce tabletop below the planned final thickness.</div></div></details>

<details class="manual-section"><summary>2. The four bottom tabs</summary><div class="manual-body"><p><strong>State</strong> is your quick overview. It shows the current world: ProZects, attention, and each ProZect's Next item.</p><p><strong>ProZects</strong> is the full list of ProZects that are still part of your current world.</p><p><strong>Archive</strong> holds ProZects you intentionally moved out of the active world. Archive is also the only place from which a ProZect can eventually be permanently deleted.</p><p><strong>More</strong> contains guides, appearance, backup/restore, ProZect Pack import, ProZect bootstrap tools, app updates, reset, and About.</p></div></details>

<details class="manual-section"><summary>3. The words StateZect uses</summary><div class="manual-body"><p><strong>ProZect</strong> — the thing you are tracking.</p><p><strong>Current situation</strong> — a short description of what is true about the ProZect right now.</p><p><strong>Stage</strong> — the broad phase, such as Drafting, Assembly, Testing, Researching, or any custom stage that makes sense to you.</p><p><strong>Lifecycle</strong> — whether the ProZect is active, paused, completed, or archived.</p><p><strong>Attention</strong> — whether the ProZect is clear, waiting, needs attention, or blocked.</p><p><strong>History</strong> — the chronological record of meaningful things that happened.</p><p><strong>Need</strong> — something the ProZect currently requires. A Need is intentionally lighter than a full task system.</p><p><strong>Next</strong> — the one open Need StateZect should treat as the next thing to focus on.</p><p><strong>Guardrail</strong> — a decision, constraint, protected behavior, or closed/open gate that should remain explicit.</p><p><strong>ProZect Brief</strong> — a readable summary generated from the structured truth already stored in StateZect.</p></div></details>

<details class="manual-section"><summary>4. Create a brand-new ProZect</summary><div class="manual-body"><ol><li>Open <strong>State</strong> or <strong>ProZects</strong>.</li><li>Tap <strong>+ ProZect</strong>.</li><li>Enter the ProZect name.</li><li>Choose the closest ProZect type: General, Software, Writing, Making / Workshop, Film / Video, or Research.</li><li>Leave <strong>New ProZect</strong> selected.</li><li>Choose a suggested stage or type your own stage.</li><li>Optionally write the first thing that should happen next. You can also tap one of StateZect's suggested Next choices.</li><li>Optionally add one Guardrail — something important you do not want forgotten.</li><li>Tap <strong>Create ProZect</strong>.</li></ol><p>You can start very small. A name plus a sensible stage is enough. Add more truth only when it becomes useful.</p></div></details>

<details class="manual-section"><summary>5. Add a ProZect that is already underway</summary><div class="manual-body"><ol><li>Tap <strong>+ ProZect</strong>.</li><li>Enter the name and ProZect type.</li><li>Choose <strong>Already underway</strong>.</li><li>Set the current stage.</li><li>Write the current situation in plain language.</li><li>Choose the current attention state.</li><li>If useful, add one important past milestone. This becomes a real History entry.</li><li>Set the current Next item.</li><li>Add an optional Guardrail.</li><li>For Software ProZects only, fill software checkpoints if you actually know them.</li><li>Create the ProZect.</li></ol><p>You do <strong>not</strong> need to reconstruct the entire past. Capture enough truth to understand the ProZect today; let clean History accumulate from here.</p></div></details>

<details class="manual-section"><summary>6. Read a ProZect screen</summary><div class="manual-body"><p>Tap any ProZect card to open it.</p><p><strong>Current state</strong> tells you what is true now: lifecycle, attention, stage, last update, current situation, and Next.</p><p><strong>Needs</strong> shows open things the ProZect requires. The Need marked with an arrow is the authoritative Next.</p><p><strong>Completed Needs</strong> keeps finished Needs for reference instead of deleting them.</p><p><strong>Guardrails</strong> preserves decisions and constraints.</p><p><strong>History</strong> shows meaningful ProZect changes over time.</p><p><strong>ProZect Brief</strong> gives you readable Quick or Full summaries.</p><p>Software ProZects also show Public/Released, Accepted Baseline, and Current Candidate checkpoints.</p></div></details>

<details class="manual-section"><summary>7. Record progress with Update State</summary><div class="manual-body"><ol><li>Open the ProZect.</li><li>Tap <strong>Update State</strong>.</li><li>Choose the update type that best describes what happened. The choices change with ProZect type.</li><li>Write the shortest useful summary of what changed.</li><li>Add detail only if it would help future-you understand the event.</li><li>Update stage, attention, situation, or checkpoints only when those truths actually changed.</li><li>Save the update.</li></ol><p>StateZect separates <strong>what is true now</strong> from <strong>what happened</strong>. Updating a ProZect can therefore change its current state and also add a History entry without treating them as the same thing.</p><div class="manual-example"><strong>Good History entry</strong><br>“Table base dry-fit successfully.”<br><br><strong>Good current situation</strong><br>“Base is assembled; tabletop still needs final sanding.”</div></div></details>

<details class="manual-section"><summary>8. Needs and the one authoritative Next</summary><div class="manual-body"><p>Add a Need when the ProZect genuinely requires something you want StateZect to remember.</p><p>Tap <strong>Next</strong> on an open Need to make it the ProZect's one authoritative Next. The ProZect card and ProZect detail should then show that same Need.</p><p>Tap <strong>Done</strong> when a Need is finished. StateZect asks for confirmation. A completed Need moves to <strong>Completed Needs</strong>; it is not silently deleted.</p><p>Use <strong>Edit</strong> to correct wording or spelling. The Edit sheet also offers <strong>Remove Need</strong> for test, junk, duplicate, or obsolete Needs. Removing a Need does not rewrite History; if it was Next, Next is cleared automatically.</p><p>If the completed Need was Next, StateZect clears it and lets you choose a replacement.</p><p>Do not create fifty microscopic Needs just because you can. StateZect works best when Needs are important enough that forgetting them would matter.</p></div></details>

<details class="manual-section"><summary>9. Guardrails</summary><div class="manual-body"><p>A Guardrail answers: <em>what must remain true?</em></p><p>Use one for a protected decision, constraint, frozen behavior, or explicit gate.</p><div class="manual-example"><strong>Software:</strong> Do not change the accepted top/header geometry.<br><strong>Writing:</strong> Keep first-person narration.<br><strong>Making:</strong> Do not reduce tabletop below final planned thickness.<br><strong>Film:</strong> Keep finished runtime under 12 minutes.</div><p>A Guardrail is not the same as a Need. “Buy screws” is a Need. “Use stainless fasteners outdoors” is closer to a Guardrail.</p></div></details>

<details class="manual-section"><summary>10. Fix or clean History safely</summary><div class="manual-body"><p><strong>Edit</strong> a History entry when the event is real but the wording/details were wrong. Edited entries show an <strong>Edited</strong> marker. If an original version exists, <strong>View original</strong> lets you inspect what was first recorded.</p><p><strong>Remove</strong> an entry when it was junk, a test, or something you do not want in normal History. Removal hides it from normal History and ProZect Briefs but keeps it recoverable.</p><p>Open <strong>Removed Entries</strong> to restore a removed entry.</p><p>Permanent erasure is deliberately harder and should be used only when you truly want that removed History record gone.</p><div class="manual-warning"><strong>Important:</strong> removing a History entry does not rewind the ProZect's current state. If the current situation itself is wrong, edit the ProZect state separately.</div></div></details>

<details class="manual-section"><summary>11. Quick Brief and Full Brief</summary><div class="manual-body"><p><strong>Quick Brief</strong> is for fast scanning or a short handoff.</p><p><strong>Full Brief</strong> includes more of the ProZect's open Needs, Guardrails, recent History, and relevant current state.</p><p>Briefs are generated from StateZect's structured data. StateZect does not store a separate narrative that can drift out of sync.</p><p>Use <strong>Copy</strong> when you want to paste a brief into a message, AI chat, document, or developer conversation. Use <strong>Share</strong> when the device share sheet is more convenient.</p></div></details>

<details class="manual-section"><summary>12. Update an existing StateZect ProZect from an AI/work chat</summary><div class="manual-body"><p>This is the safest manual assisted-update workflow:</p><ol><li>Open the ProZect in StateZect.</li><li>Choose <strong>Generate Update Prompt</strong>.</li><li>Copy the generated prompt.</li><li>Paste it into the authoritative chat/work context for that ProZect. That might be an AI development chat today or another approved workflow later.</li><li>The outside chat should return one structured StateZect ProZect Update Packet JSON object.</li><li>Copy the returned JSON.</li><li>Back in StateZect, choose <strong>Paste Update Packet</strong>. If you saved the packet as a file instead, use <strong>Import Packet File</strong>.</li><li>StateZect parses and validates it, then shows <strong>Preview ProZect Update</strong>.</li><li>Read the preview. Nothing has been applied yet.</li><li>If the proposed changes are correct, tap <strong>Apply Update</strong>.</li></ol><p>StateZect may repair harmless AI formatting such as smart quotation marks or one Markdown JSON fence, but the packet must still pass the strict Update Packet schema.</p><p>If StateZect warns that the packet was created from an older ProZect revision, review it carefully. The ProZect changed after the prompt was generated.</p><p>Applying the exact same packet twice is rejected so History is not duplicated.</p></div></details>

<details class="manual-section"><summary>13. Bootstrap an existing ProZect from an AI/work chat</summary><div class="manual-body"><p>Use Bootstrap when the ProZect exists in real life or another work context but is <strong>not in StateZect yet</strong>.</p><ol><li>Tap <strong>+ ProZect</strong> and choose <strong>Bootstrap an existing ProZect from work / AI chat</strong>, or use the Bootstrap tools under More.</li><li>Choose the ProZect type. If you already know the ProZect name, provide it.</li><li>Generate the Bootstrap Prompt. StateZect pins a stable ProZect ID.</li><li>Paste the prompt into the authoritative work/AI chat.</li><li>Bring the returned Bootstrap Packet JSON back to StateZect by paste or file.</li><li>Read <strong>Preview ProZect Bootstrap</strong>. The ProZect does not exist in StateZect yet.</li><li>If the preview is correct, tap <strong>Create ProZect</strong>.</li></ol><p>Bootstrap can create the current ProZect state, useful past milestones, Needs/Next, and Guardrails together. The same packet cannot be applied twice.</p></div></details>

<details class="manual-section"><summary>14. Understand the four data-transfer tools</summary><div class="manual-body"><p><strong>Full Backup</strong> — a complete snapshot of this StateZect database. Export it for safety. Restoring it <strong>replaces</strong> the current local StateZect database after validation.</p><p><strong>ProZect Pack</strong> — one or more ordinary ProZects meant to be merged/refreshed into StateZect. It does not delete unrelated local ProZects. This is what NivareQ's curated ProZect Pack uses.</p><p><strong>Update Packet</strong> — proposed changes to one ProZect that already exists in StateZect. It always goes through Preview before Apply.</p><p><strong>Bootstrap Packet</strong> — proposed initial structured data for a ProZect that is not yet in StateZect. It always goes through Preview before Create.</p><div class="manual-warning"><strong>Do not confuse ProZect Pack with Full Backup.</strong> If you only want to add/refresh ProZects, use ProZect Pack. Use Full Backup restore only when you intentionally want the whole local StateZect database replaced.</div></div></details>

<details class="manual-section"><summary>15. Export and restore a Full Backup</summary><div class="manual-body"><p><strong>To export:</strong></p><ol><li>Open More.</li><li>Tap <strong>Export backup</strong>.</li><li>Keep the downloaded JSON file somewhere you trust.</li></ol><p><strong>To restore:</strong></p><ol><li>Open More.</li><li>Tap <strong>Choose backup</strong> under Restore full backup.</li><li>Select the backup file.</li><li>Read the replacement warning.</li><li>Only continue if you truly want the current StateZect database replaced by that backup.</li></ol><p>If you merely want to refresh NivareQ ProZects or add ProZects from somebody else, this is probably the wrong tool; use ProZect Pack instead.</p></div></details>

<details class="manual-section"><summary>16. Import a ProZect Pack</summary><div class="manual-body"><ol><li>Open More.</li><li>Tap <strong>Choose ProZect Pack</strong>.</li><li>Select the ProZect Pack JSON file.</li><li>Read the merge explanation.</li><li>Tap the confirm/merge action.</li></ol><p>StateZect adds missing records and refreshes matching records when the incoming data is newer. It can also resolve known Needs or Guardrails when the pack contains their newer state. Unrelated local ProZects remain.</p><p>If you import the same current pack again, StateZect should simply report that the pack is already current or apply only genuinely newer records.</p></div></details>

<details class="manual-section"><summary>17. Archive, restore, and permanently delete a ProZect</summary><div class="manual-body"><p><strong>Archive</strong> removes a ProZect from the active world without destroying it. Its History, Needs, and Guardrails remain.</p><p>Open Archive and open the ProZect to restore it.</p><p>A ProZect cannot be permanently deleted while it is active. Permanent deletion is available only after Archive.</p><p>Permanent deletion requires an explicit warning, the exact ProZect name, and final confirmation. It removes the ProZect and its owned History, Needs, and Guardrails.</p><div class="manual-warning"><strong>If you are a family member or employee using somebody else's StateZect:</strong> do not permanently delete a ProZect unless you are certain you were authorized to do so.</div></div></details>

<details class="manual-section"><summary>18. Complete Reset — the nuclear option</summary><div class="manual-body"><p><strong>Reset StateZect</strong> erases all local StateZect ProZect data and returns the app to a blank fresh-install state. It is not the same as archiving one ProZect.</p><p>The reset requires multiple confirmations, including typing <strong>RESET</strong>.</p><p>Before resetting, export a Full Backup if there is any possibility the existing data may be wanted later.</p><p>After reset, the default Night theme is restored.</p></div></details>

<details class="manual-section"><summary>19. Themes</summary><div class="manual-body"><p>Open More → Appearance and choose <strong>Day</strong>, <strong>Night</strong>, <strong>OLED</strong>, <strong>Dusk</strong>, <strong>Ocean</strong>, <strong>Forest</strong>, <strong>Ember</strong>, <strong>Plum</strong>, or <strong>Sand</strong>.</p><p>The selection is remembered on the device. Themes change presentation only; they do not change ProZect data.</p></div></details>

<details class="manual-section"><summary>20. App updates</summary><div class="manual-body"><p>StateZect checks for a newer deployed app shell on launch and when the installed app returns to the foreground.</p><p>If you think a new build was deployed but StateZect has not picked it up, open More → <strong>Check for updates</strong>.</p><p>The update system concerns the app itself. Your ProZect data lives separately in IndexedDB and should not require a reset just because the app shell was updated, unless a future release explicitly says otherwise.</p></div></details>

<details class="manual-section"><summary>21. Common mistakes and what to do</summary><div class="manual-body"><p><strong>I made a test History entry.</strong><br>Remove it from normal History. If needed later, restore it from Removed Entries. Permanently erase only when truly necessary.</p><p><strong>I wrote a real History entry incorrectly.</strong><br>Edit it. StateZect marks it Edited and can show the original.</p><p><strong>A Need has a typo or was only test/junk data.</strong><br>Tap Edit. Correct the wording and Save, or Remove Need and confirm if the Need should not exist.</p><p><strong>The wrong Need is marked Next.</strong><br>Tap Next on the correct open Need. StateZect keeps one authoritative Next.</p><p><strong>I finished the Next Need.</strong><br>Tap Done, confirm, then choose a replacement Next if there is one.</p><p><strong>I received a NivareQ ProZect data file.</strong><br>If it is a ProZect Pack, use Import ProZect Pack — not Restore full backup.</p><p><strong>An AI returned JSON with curly quotes or a code fence.</strong><br>Try Paste/Import normally. StateZect can repair a narrow set of harmless formatting defects before strict validation.</p><p><strong>An Update Packet says it is stale.</strong><br>The StateZect ProZect changed after the prompt was generated. Read Preview carefully. If uncertain, generate a fresh prompt from the current ProZect and ask the authoritative chat for a new packet.</p><p><strong>I am not sure whether to delete or reset something.</strong><br>Do not. Export a backup and ask the owner/maintainer first.</p></div></details>

<details class="manual-section"><summary>22. Simple examples for different ProZect types</summary><div class="manual-body"><div class="manual-example"><strong>Writing</strong><br>Stage: Revising<br>Current: First full draft exists; opening needs restructuring.<br>Next: Rewrite opening chapter.<br>Need: Verify historical date.<br>Guardrail: Keep first-person narration.</div><div class="manual-example"><strong>Making / Workshop</strong><br>Stage: Assembly<br>Current: Base assembled; tabletop unfinished.<br>Next: Sand tabletop.<br>Need: Buy finish.<br>Guardrail: Preserve planned tabletop thickness.</div><div class="manual-example"><strong>Film / Video</strong><br>Stage: Pre-production<br>Current: Script locked; two locations confirmed.<br>Next: Finish shot list.<br>Need: Exterior-location permission.<br>Guardrail: Keep runtime under 12 minutes.</div><div class="manual-example"><strong>Software</strong><br>Stage: Testing<br>Current: Current candidate is under real-device acceptance.<br>Next: Complete acceptance checklist.<br>Need: Verify offline cold launch.<br>Guardrail: Do not change the accepted shell geometry.</div></div></details>

<details class="manual-section"><summary>23. If StateZect was handed to you by somebody else</summary><div class="manual-body"><ol><li>Open StateZect and look at the ProZect cards before changing anything.</li><li>Open the relevant ProZect and read Current State, Next, open Needs, and Guardrails.</li><li>If you only need a summary, use Quick Brief or Full Brief rather than editing data.</li><li>When recording progress, prefer Update State over rewriting History manually.</li><li>Do not retire Guardrails, archive ProZects, restore Full Backups, permanently delete, or Complete Reset unless you understand why and are authorized.</li><li>Before any high-impact data operation, export a Full Backup.</li><li>If an instruction conflicts with a Guardrail, stop and ask the ProZect owner.</li></ol></div></details>

<details class="manual-section"><summary>24. One-minute cheat sheet</summary><div class="manual-body"><p><strong>Something meaningful happened?</strong> → Update State.</p><p><strong>The ProZect requires something?</strong> → Add a Need.</p><p><strong>One Need should be the focus?</strong> → Make it Next.</p><p><strong>A decision/constraint must stay true?</strong> → Add a Guardrail.</p><p><strong>Need a readable summary?</strong> → Quick Brief or Full Brief.</p><p><strong>History wording was wrong?</strong> → Edit; View original remains available.</p><p><strong>History was junk/test data?</strong> → Remove; restore later if needed.</p><p><strong>Refresh several ProZects?</strong> → Import ProZect Pack.</p><p><strong>Replace the entire local database?</strong> → Restore Full Backup — only intentionally.</p><p><strong>Update one existing ProZect from an outside work/AI chat?</strong> → Generate Update Prompt → JSON → Preview → Apply.</p><p><strong>Bring an already-existing outside ProZect into StateZect?</strong> → Bootstrap Prompt → JSON → Preview → Create.</p><p><strong>Done with a ProZect for now?</strong> → Archive. Do not permanently delete unless you truly mean it.</p></div></details>
</div>`);}

async function acceptCandidate(p){const result=promoteCandidate(p);await savePulse(result.project,result.entry);await refresh();renderProject();toast('Candidate accepted');}
function confirmArchive(p){openSheet('Archive ProZect',`<p class="notice">${esc(p.name)} will leave the active ProZect list. Its History and Needs stay preserved and it can be restored.</p><div class="form-actions"><button class="ghost-btn" data-close2>Cancel</button><button class="danger-btn" id="confirm-archive">Archive</button></div>`,sheet=>{sheet.querySelector('[data-close2]').onclick=closeModal;sheet.querySelector('#confirm-archive').onclick=async()=>{const archived=archiveProject(p);const entry={id:`pulse_${crypto.randomUUID()}`,projectId:p.id,occurredAt:new Date().toISOString(),kind:'Archived',summary:'ProZect archived',detail:'',changes:{lifecycle:{from:p.lifecycle,to:'archived'}},updatedAt:new Date().toISOString(),editedAt:null,original:null,removedAt:null};await savePulse(archived,entry);closeModal();await refresh();selectedProjectId=null;view='archive';render();};});}
async function restore(p){const restored=restoreProject(p);const entry={id:`pulse_${crypto.randomUUID()}`,projectId:p.id,occurredAt:new Date().toISOString(),kind:'Restored',summary:'ProZect restored from Archive',detail:'',changes:{lifecycle:{from:'archived',to:'active'}},updatedAt:new Date().toISOString(),editedAt:null,original:null,removedAt:null};await savePulse(restored,entry);closeModal();await refresh();renderProject();toast('ProZect restored');}
function openDelete(p){openSheet('Permanent deletion',`<p class="notice">This permanently removes the ProZect, its History, Needs, and Guardrails. There is no undo inside StateZect.</p><label>Type the ProZect name to continue</label><input id="delete-name" autocomplete="off" placeholder="${esc(p.name)}"><label><input style="width:auto" id="delete-check" type="checkbox"> I understand this is permanent</label><button class="danger-btn wide" id="final-delete" style="margin-top:16px">Delete permanently</button>`,sheet=>{sheet.querySelector('#final-delete').onclick=async()=>{try{if(!sheet.querySelector('#delete-check').checked)throw new Error('Final deletion confirmation is incomplete.');assertCanDelete(p,sheet.querySelector('#delete-name').value,'FINAL_DELETE');await deleteProjectCascade(p.id);closeModal();await refresh();selectedProjectId=null;view='archive';render();toast('ProZect permanently deleted');}catch(err){alert(err.message);}};});}
function openCompleteReset(){openSheet('Reset all StateZect data?',`<p class="notice danger-notice"><strong>This returns StateZect to a blank fresh-install state.</strong><br><br>All ProZects, History, Needs, and Guardrails stored on this device will be permanently erased. Export a backup first if you may want the data again.</p><button class="danger-btn wide" id="reset-continue">Continue</button>`,sheet=>{sheet.querySelector('#reset-continue').onclick=()=>{openSheet('Final reset confirmation',`<p class="notice danger-notice">There is no in-app undo after this step.</p><label><input style="width:auto" id="reset-check" type="checkbox"> I understand all local StateZect ProZect data will be erased</label><label>Type <strong>RESET</strong> to confirm</label><input id="reset-word" autocomplete="off" autocapitalize="characters" placeholder="RESET"><button class="danger-btn wide" id="reset-final" style="margin-top:16px">Erase everything</button>`,confirmSheet=>{confirmSheet.querySelector('#reset-final').onclick=async()=>{if(!confirmSheet.querySelector('#reset-check').checked||confirmSheet.querySelector('#reset-word').value.trim()!=='RESET'){alert('Reset confirmation is incomplete.');return;}await resetAllData();try{localStorage.removeItem(THEME_KEY);}catch{}applyTheme('night',{persist:false});closeModal();await refresh();view='pulse';selectedProjectId=null;render();toast('StateZect reset complete');};});};});}

async function exportBackup(){const all=await readAll();const backup=makeBackup({projects:all.projects,entries:all.pulseEntries,needs:all.needs,guardrails:all.guardrails});const blob=new Blob([JSON.stringify(backup,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`StateZect-Backup-${new Date().toISOString().slice(0,10)}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),500);}
async function importBackup(e){const file=e.target.files?.[0];if(!file)return;try{const data=JSON.parse(await file.text());openSheet('Replace StateZect data?',`<p class="notice">This full restore replaces all current ProZects, History, Needs, and Guardrails after validation.</p><div class="form-actions"><button class="ghost-btn" data-close2>Cancel</button><button class="danger-btn" id="confirm-import">Validate & replace</button></div>`,sheet=>{sheet.querySelector('[data-close2]').onclick=closeModal;sheet.querySelector('#confirm-import').onclick=async()=>{try{await replaceAllFromBackup(data);closeModal();await refresh();view='pulse';selectedProjectId=null;render();toast('StateZect data imported');}catch(err){alert(err.message);}};});}catch{alert('That file is not valid JSON.');}finally{e.target.value='';}}
async function importProjectPack(e){const file=e.target.files?.[0];if(!file)return;try{const data=JSON.parse(await file.text());openSheet('Merge ProZect Pack?',`<p class="notice">This adds/refreshes matching records when the incoming record is newer. Known Needs and Guardrails can therefore be resolved or updated without deleting unrelated local work.</p><div class="form-actions"><button class="ghost-btn" data-close2>Cancel</button><button class="primary-btn" id="confirm-pack">Validate & merge</button></div>`,sheet=>{sheet.querySelector('[data-close2]').onclick=closeModal;sheet.querySelector('#confirm-pack').onclick=async()=>{try{const result=await mergeProjectPack(data);closeModal();await refresh();view='pulse';selectedProjectId=null;render();const changed=Object.entries(result).filter(([k])=>k!=='projectsKept').reduce((sum,[,v])=>sum+v,0);toast(changed?`ProZect Pack merged · ${changed} updates`:'ProZect Pack already current');}catch(err){alert(err.message);}};});}catch{alert('That file is not valid JSON.');}finally{e.target.value='';}}

app.addEventListener('click',event=>{const card=event.target.closest?.('[data-project]');if(!card||!app.contains(card))return;event.preventDefault();selectedProjectId=card.dataset.project;void renderProject().catch(error=>{console.error('StateZect could not open project detail:',error);selectedProjectId=null;toast('Could not open ProZect');});});

applyTheme(currentTheme(),{persist:false});
await ensureMeta();
await refresh();
render();
await initPwaRuntime({onStatus:toast});
